# 方法一：DP（標準解法 + 優化）
class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if not prices or k == 0:
            return 0

        n = len(prices)

        # 優化：k 很大時等同於無限次交易
        if k >= n // 2:
            return self.maxProfitUnlimited(prices)

        # buy[j] = 完成 j 次交易，持有股票的最大利潤
        # sell[j] = 完成 j 次交易，不持有股票的最大利潤
        buy = [-float('inf')] * (k + 1)
        sell = [0] * (k + 1)

        for price in prices:
            # 從後往前更新，避免覆蓋
            for j in range(k, 0, -1):
                sell[j] = max(sell[j], buy[j] + price)
                buy[j] = max(buy[j], sell[j - 1] - price)

        return sell[k]

    def maxProfitUnlimited(self, prices):
        """無限次交易的貪心解法"""
        profit = 0
        for i in range(1, len(prices)):
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit


# 方法二：二維 DP（更清晰）
class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if not prices or k == 0:
            return 0

        n = len(prices)
        if k >= n // 2:
            profit = 0
            for i in range(1, n):
                profit += max(0, prices[i] - prices[i - 1])
            return profit

        # buy[i][j] = 第 i 天完成 j 次交易，持有股票
        # sell[i][j] = 第 i 天完成 j 次交易，不持有股票
        buy = [[-float('inf')] * (k + 1) for _ in range(n)]
        sell = [[0] * (k + 1) for _ in range(n)]

        # 初始化第一天
        for j in range(k + 1):
            buy[0][j] = -prices[0]

        for i in range(1, n):
            for j in range(k, 0, -1):
                buy[i][j] = max(buy[i - 1][j], sell[i - 1][j] - prices[i])
                sell[i][j] = max(sell[i - 1][j], buy[i - 1][j - 1] + prices[i])

        return sell[n - 1][k]


# 方法三：詳細註解版本
class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        """
        股票交易系列最難版本

        狀態定義：
        buy[j]：完成 j 次交易，當前持有股票的最大利潤
        sell[j]：完成 j 次交易，當前不持有股票的最大利潤
        """
        if not prices or k == 0:
            return 0

        n = len(prices)

        # 關鍵優化：k 過大時的處理
        # 如果 k >= n//2，等同於無限次交易
        if k >= n // 2:
            # 貪心：抓住每次上漲
            profit = 0
            for i in range(1, n):
                if prices[i] > prices[i - 1]:
                    profit += prices[i] - prices[i - 1]
            return profit

        # 初始化
        # buy[j] 初始為負無窮（不可能持有股票）
        # sell[j] 初始為 0（不操作）
        buy = [-float('inf')] * (k + 1)
        sell = [0] * (k + 1)

        # 遍歷每一天
        for price in prices:
            # 從後往前更新，避免同一天的狀態互相影響
            for j in range(k, 0, -1):
                # 賣出：完成第 j 次交易
                # 選擇：保持不持有 vs 今天賣出
                sell[j] = max(sell[j], buy[j] + price)

                # 買入：準備第 j 次交易
                # 選擇：保持持有 vs 今天買入
                buy[j] = max(buy[j], sell[j - 1] - price)

        # 最終答案：完成 k 次交易，不持有股票
        return sell[k]


# 方法四：空間優化到 O(k)
class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if not prices or k == 0:
            return 0

        n = len(prices)
        if k >= n // 2:
            return sum(max(0, prices[i] - prices[i-1]) for i in range(1, n))

        buy = [-prices[0]] * (k + 1)
        sell = [0] * (k + 1)

        for i in range(1, n):
            for j in range(k, 0, -1):
                sell[j] = max(sell[j], buy[j] + prices[i])
                buy[j] = max(buy[j], sell[j - 1] - prices[i])

        return sell[k]

